#' IV Regression
#'
#' 
#' @param data .
#' @param outcome .
#' @param endog .
#' @param instruments .
#' @param controls .
#' @param absorb .
#' @param cluster .
#' @param weights .
#' @param method .
#' @param alpha .
#' @param kvalue .
#' @param vce .
#' @param small .
#' @param level .
#' @param showOls .
#' @param showFirst .
#' @param showControls .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$coef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ols} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$firstF} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$first} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$coef$asDF}
#'
#' \code{as.data.frame(results$coef)}
#'
#' @export
iv <- function(
    data,
    outcome,
    endog,
    instruments,
    controls,
    absorb,
    cluster,
    weights,
    method = "2sls",
    alpha = 1,
    kvalue = 1,
    vce = "classical",
    small = TRUE,
    level = 95,
    showOls = TRUE,
    showFirst = TRUE,
    showControls = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("iv requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(endog)) endog <- jmvcore::resolveQuo(jmvcore::enquo(endog))
    if ( ! missing(instruments)) instruments <- jmvcore::resolveQuo(jmvcore::enquo(instruments))
    if ( ! missing(controls)) controls <- jmvcore::resolveQuo(jmvcore::enquo(controls))
    if ( ! missing(absorb)) absorb <- jmvcore::resolveQuo(jmvcore::enquo(absorb))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(endog), endog, NULL),
            `if`( ! missing(instruments), instruments, NULL),
            `if`( ! missing(controls), controls, NULL),
            `if`( ! missing(absorb), absorb, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(weights), weights, NULL))


    options <- ivOptions$new(
        outcome = outcome,
        endog = endog,
        instruments = instruments,
        controls = controls,
        absorb = absorb,
        cluster = cluster,
        weights = weights,
        method = method,
        alpha = alpha,
        kvalue = kvalue,
        vce = vce,
        small = small,
        level = level,
        showOls = showOls,
        showFirst = showFirst,
        showControls = showControls,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- ivClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

